// The member roles, owner first, and the sets of roles that may call the endpoint groups.
var (
	allRoles = []store.Role{store.RoleOwner, store.RoleAdmin, store.RoleBilling, store.RoleMember, store.RoleViewer}
	everyone = allRoles
	writers  = []store.Role{store.RoleOwner, store.RoleAdmin, store.RoleBilling, store.RoleMember}
	billers  = []store.Role{store.RoleOwner, store.RoleAdmin, store.RoleBilling}
	managers = []store.Role{store.RoleOwner, store.RoleAdmin}
)

// member is a member of Acme and their API key.
type member struct{ id, key string }

// addRoles gives Acme a member of each role besides its owner, and returns all of them by role.
func addRoles(e *apitest.Env) map[store.Role]member {
	ms := map[store.Role]member{store.RoleOwner: {e.Acme.Owner.ID, e.Acme.Key}}
	for _, r := range allRoles[1:] {
		u, key := e.AddMember(e.Acme, string(r)+"@acme.example", r)
		ms[r] = member{u.ID, key}
	}
	return ms
}

// fixture is one of each object the gates act on, made by Acme's owner. Paths and bodies name them with {placeholders}.
type fixture struct {
	customer, spare, plan, sub, meteredSub, invoice, endpoint, event, invite string
}

func newFixture(t *testing.T, e *apitest.Env) fixture {
	t.Helper()
	customer := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	spare := e.CreateCustomer(e.Acme, "Spare", "spare@example.com")
	plan := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	var metered store.Plan
	e.MustDo(http.StatusCreated, "POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "Usage", "currency": "USD", "price": "0.10", "interval": "month", "usage_type": store.Metered}, &metered)
	var sub, meteredSub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": customer.ID, "plan_id": plan.ID, "quantity": 2}, &sub)
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": customer.ID, "plan_id": metered.ID, "quantity": 1}, &meteredSub)
	var invs struct{ Items []struct{ ID string } }
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?customer_id="+customer.ID, e.Acme.Key, nil, &invs)
	var evs struct{ Items []struct{ ID string } }
	e.MustDo(http.StatusOK, "GET", "/v1/events", e.Acme.Key, nil, &evs)
	if len(invs.Items) == 0 || len(evs.Items) == 0 {
		t.Fatalf("fixture: invoices %d, events %d", len(invs.Items), len(evs.Items))
	}
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"customer.created"}}, &ep)
	var inv store.Invite
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "invitee@people.example", "role": "member"}, &inv)
	return fixture{customer: customer.ID, spare: spare.ID, plan: plan.ID, sub: sub.ID, meteredSub: meteredSub.ID,
		invoice: invs.Items[0].ID, endpoint: ep.ID, event: evs.Items[0].ID, invite: inv.ID}
}

func (f fixture) fill(s string) string {
	return strings.NewReplacer("{customer}", f.customer, "{spare}", f.spare, "{plan}", f.plan, "{sub}", f.sub,
		"{metered_sub}", f.meteredSub, "{invoice}", f.invoice, "{endpoint}", f.endpoint, "{event}", f.event, "{invite}", f.invite).Replace(s)
}

// stateJSON is everything the store holds, to check that a refused request changed nothing.
func stateJSON(t *testing.T, e *apitest.Env) string {
	t.Helper()
	b, err := json.Marshal(e.Store.Export())
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

// gate is an endpoint and the roles that may call it. An allowed role gets want; any other role gets 403 and changes nothing.
type gate struct {
	method, path, body string
	allow              []store.Role
	want               int
}

func TestRolesGateEndpoints(t *testing.T) {
	gates := []gate{
		{"GET", "/v1/org", "", everyone, 200},
		{"PATCH", "/v1/org", `{"name":"Acme 2"}`, managers, 200},
		{"GET", "/v1/members", "", everyone, 200},
		{"GET", "/v1/invites", "", everyone, 200},
		{"POST", "/v1/invites", `{"email":"new@people.example","role":"member"}`, managers, 201},
		{"DELETE", "/v1/invites/{invite}", "", managers, 204},
		{"GET", "/v1/api-keys", "", everyone, 200},
		{"POST", "/v1/api-keys", `{"name":"CI"}`, everyone, 201},
		{"GET", "/v1/customers", "", everyone, 200},
		{"GET", "/v1/customers/export.csv", "", everyone, 200},
		{"GET", "/v1/customers/{customer}", "", everyone, 200},
		{"POST", "/v1/customers", `{"name":"New","email":"new@example.com"}`, writers, 201},
		{"PATCH", "/v1/customers/{customer}", `{"name":"Jane 2"}`, writers, 200},
		{"DELETE", "/v1/customers/{spare}", "", writers, 204},
		{"GET", "/v1/plans", "", everyone, 200},
		{"GET", "/v1/plans/{plan}", "", everyone, 200},
		{"POST", "/v1/plans", `{"name":"Pro","currency":"USD","price":"5.00","interval":"month"}`, billers, 201},
		{"PATCH", "/v1/plans/{plan}", `{"name":"Team 2"}`, billers, 200},
		{"GET", "/v1/subscriptions", "", everyone, 200},
		{"GET", "/v1/subscriptions/{sub}", "", everyone, 200},
		{"POST", "/v1/subscriptions", `{"customer_id":"{spare}","plan_id":"{plan}","quantity":1}`, writers, 201},
		{"PATCH", "/v1/subscriptions/{sub}", `{"quantity":3}`, writers, 200},
		{"POST", "/v1/subscriptions/{metered_sub}/usage", `{"quantity":5}`, writers, 201},
		{"POST", "/v1/subscriptions/{sub}/cancel", "", writers, 200},
		{"GET", "/v1/invoices", "", everyone, 200},
		{"GET", "/v1/invoices/{invoice}", "", everyone, 200},
		{"GET", "/v1/invoices/{invoice}/lines", "", everyone, 200},
		{"GET", "/v1/payments", "", everyone, 200},
		{"POST", "/v1/invoices", `{"customer_id":"{spare}","currency":"USD","lines":[{"description":"Setup","quantity":1,"unit_amount":1000}]}`, billers, 201},
		{"POST", "/v1/invoices/{invoice}/pay", "", billers, 422}, // no payment method: allowed, and nothing is charged
		{"POST", "/v1/invoices/{invoice}/void", "", billers, 200},
		{"GET", "/v1/reports/revenue?from=2026-01-01&to=2026-01-31", "", billers, 200},
		{"GET", "/v1/webhook-endpoints", "", managers, 200},
		{"POST", "/v1/webhook-endpoints", `{"url":"https://hooks.acme.example/new","events":["*"]}`, managers, 201},
		{"GET", "/v1/webhook-endpoints/{endpoint}", "", managers, 200},
		{"PATCH", "/v1/webhook-endpoints/{endpoint}", `{"enabled":false}`, managers, 200},
		{"GET", "/v1/webhook-endpoints/{endpoint}/deliveries", "", managers, 200},
		{"GET", "/v1/events", "", managers, 200},
		{"GET", "/v1/events/{event}", "", managers, 200},
		{"DELETE", "/v1/webhook-endpoints/{endpoint}", "", managers, 204},
	}
	for _, g := range gates {
		for _, role := range allRoles {
			t.Run(g.method+" "+g.path+" "+string(role), func(t *testing.T) {
				e := apitest.New(t)
				ms := addRoles(e)
				f := newFixture(t, e)
				before := stateJSON(t, e)
				r := e.Do(g.method, f.fill(g.path), ms[role].key, f.fill(g.body))
				if slices.Contains(g.allow, role) {
					if r.Code != g.want {
						t.Fatalf("%s: want %d, got %s", role, g.want, r)
					}
					return
				}
				if r.Code != http.StatusForbidden || r.Map(t)["error"] != "forbidden" {
					t.Fatalf("%s: want 403 forbidden, got %s", role, r)
				}
				if after := stateJSON(t, e); after != before {
					t.Fatalf("%s: a refused request changed the store", role)
				}
			})
		}
	}
}

func TestChangingRoles(t *testing.T) {
	cases := []struct {
		name          string
		who, target   store.Role
		role          store.Role
		want          int
		wantErr       string
	}{
		{"admin grants admin", store.RoleAdmin, store.RoleMember, store.RoleAdmin, 403, "forbidden"},
		{"admin grants billing", store.RoleAdmin, store.RoleMember, store.RoleBilling, 200, ""},
		{"admin changes an owner", store.RoleAdmin, store.RoleOwner, store.RoleBilling, 403, "forbidden"},
		{"admin changes an admin", store.RoleAdmin, store.RoleAdmin, store.RoleMember, 403, "forbidden"},
		{"admin changes itself", store.RoleAdmin, store.RoleAdmin, store.RoleMember, 403, "forbidden"},
		{"owner changes itself", store.RoleOwner, store.RoleOwner, store.RoleAdmin, 403, "forbidden"},
		{"owner demotes an admin", store.RoleOwner, store.RoleAdmin, store.RoleBilling, 200, ""},
		{"owner grants owner", store.RoleOwner, store.RoleMember, store.RoleOwner, 200, ""},
		{"owner grants an unknown role", store.RoleOwner, store.RoleMember, "superuser", 422, "invalid"},
		{"admin grants an unknown role", store.RoleAdmin, store.RoleMember, "superuser", 422, "invalid"},
		{"billing changes a member", store.RoleBilling, store.RoleMember, store.RoleViewer, 403, "forbidden"},
		{"member changes a viewer", store.RoleMember, store.RoleViewer, store.RoleMember, 403, "forbidden"},
		{"viewer changes a member", store.RoleViewer, store.RoleMember, store.RoleViewer, 403, "forbidden"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			e := apitest.New(t)
			ms := addRoles(e)
			target := ms[c.target]
			r := e.Do("PATCH", "/v1/members/"+target.id, ms[c.who].key, map[string]string{"role": string(c.role)})
			if r.Code != c.want || (c.wantErr != "" && r.Map(t)["error"] != c.wantErr) {
				t.Fatalf("want %d %s, got %s", c.want, c.wantErr, r)
			}
			m, _ := e.Store.Member(e.Acme.ID, target.id)
			if c.want == 200 && m.Role != c.role {
				t.Fatalf("role = %s, want %s", m.Role, c.role)
			}
			if c.want != 200 && m.Role != c.target {
				t.Fatalf("a refused change moved the role to %s", m.Role)
			}
		})
	}
}

