// A role change applies to the member's existing keys at once.
func TestRoleChangeAppliesToExistingKeys(t *testing.T) {
	e := apitest.New(t)
	ms := addRoles(e)
	customer := map[string]string{"name": "New", "email": "new@example.com"}
	e.MustDo(http.StatusCreated, "POST", "/v1/customers", ms[store.RoleMember].key, customer, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+ms[store.RoleMember].id, e.Acme.Key, map[string]string{"role": "viewer"}, nil)
	if r := e.Do("POST", "/v1/customers", ms[store.RoleMember].key, map[string]string{"name": "Newer", "email": "newer@example.com"}); r.Code != http.StatusForbidden {
		t.Fatalf("demoted member writes: %s", r)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/customers", ms[store.RoleMember].key, nil, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+ms[store.RoleMember].id, e.Acme.Key, map[string]string{"role": "member"}, nil)
	e.MustDo(http.StatusCreated, "POST", "/v1/customers", ms[store.RoleMember].key, map[string]string{"name": "Newer", "email": "newer@example.com"}, nil)
}

func TestRemovingMembers(t *testing.T) {
	e := apitest.New(t)
	ms := addRoles(e)
	owner, admin, billing, member, viewer := ms[store.RoleOwner], ms[store.RoleAdmin], ms[store.RoleBilling], ms[store.RoleMember], ms[store.RoleViewer]

	// Removing someone else: owners and admins only, and not owners or admins unless one is an owner.
	e.MustDo(http.StatusForbidden, "DELETE", "/v1/members/"+billing.id, member.key, nil, nil)
	e.MustDo(http.StatusForbidden, "DELETE", "/v1/members/"+billing.id, viewer.key, nil, nil)
	e.MustDo(http.StatusForbidden, "DELETE", "/v1/members/"+owner.id, admin.key, nil, nil)
	e.MustDo(http.StatusNotFound, "DELETE", "/v1/members/usr_nope", owner.key, nil, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+billing.id, admin.key, nil, nil)

	// Anyone may leave, whatever their role.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+viewer.id, viewer.key, nil, nil)
	e.MustDo(http.StatusUnauthorized, "GET", "/v1/org", viewer.key, nil, nil)

	// Another owner lets the first one leave; the last owner cannot, and their refused leave changes nothing.
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+member.id, owner.key, map[string]string{"role": "owner"}, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+owner.id, owner.key, nil, nil)
	r := e.Do("DELETE", "/v1/members/"+member.id, member.key, nil)
	if r.Code != http.StatusConflict || r.Map(t)["error"] != "last_owner" {
		t.Fatalf("the last owner leaves: %s", r)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/org", member.key, nil, nil)
}

func TestInvitingByRole(t *testing.T) {
	for _, who := range []store.Role{store.RoleOwner, store.RoleAdmin} {
		for _, grant := range []store.Role{store.RoleOwner, store.RoleAdmin, store.RoleMember} {
			t.Run(string(who)+" invites "+string(grant), func(t *testing.T) {
				e := apitest.New(t)
				ms := addRoles(e)
				want := http.StatusCreated
				if who == store.RoleAdmin && grant != store.RoleMember {
					want = http.StatusForbidden
				}
				r := e.Do("POST", "/v1/invites", ms[who].key, map[string]string{"email": "new@people.example", "role": string(grant)})
				if r.Code != want {
					t.Fatalf("want %d, got %s", want, r)
				}
			})
		}
	}
}

func TestAPIKeysByRole(t *testing.T) {
	e := apitest.New(t)
	ms := addRoles(e)
	var all struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", e.Acme.Key, nil, &all)
	if len(all.Items) != 5 {
		t.Fatalf("the owner sees %d keys, want 5", len(all.Items))
	}
	keyID := map[string]string{}
	for _, k := range all.Items {
		keyID[k.Name] = k.ID
	}
	adminKey, memberKey := keyID["Key of admin@acme.example"], keyID["Key of member@acme.example"]
	var mine struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", ms[store.RoleViewer].key, nil, &mine)
	if len(mine.Items) != 1 || mine.Items[0].UserID != ms[store.RoleViewer].id {
		t.Fatalf("the viewer sees %+v, want only their own key", mine.Items)
	}
	var admin struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", ms[store.RoleAdmin].key, nil, &admin)
	if len(admin.Items) != 5 {
		t.Fatalf("the admin sees %d keys, want 5", len(admin.Items))
	}

	// Everyone may create a key for themselves.
	for role, m := range ms {
		e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", m.key, map[string]string{"name": "extra " + string(role)}, nil)
	}

	// Revoking: your own key always; anyone's for owners and admins; another member's key is 403 and still works.
	e.MustDo(http.StatusForbidden, "DELETE", "/v1/api-keys/"+adminKey, memberKey2(ms), nil, nil)
	e.MustDo(http.StatusOK, "GET", "/v1/org", ms[store.RoleAdmin].key, nil, nil)
	e.MustDo(http.StatusNotFound, "DELETE", "/v1/api-keys/key_nope", e.Acme.Key, nil, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+memberKey, ms[store.RoleAdmin].key, nil, nil)
	e.MustDo(http.StatusUnauthorized, "GET", "/v1/org", ms[store.RoleMember].key, nil, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+keyID["Key of viewer@acme.example"], ms[store.RoleViewer].key, nil, nil)
	e.MustDo(http.StatusUnauthorized, "GET", "/v1/org", ms[store.RoleViewer].key, nil, nil)
}

// memberKey2 is the key of the member whose own key the cases above do not revoke, so a refused revoke is tried from a
// key that stays valid.
func memberKey2(ms map[store.Role]member) string { return ms[store.RoleMember].key }

func TestWebhookEndpointsStayInOrg(t *testing.T) {
	e := apitest.New(t)
	ms := addRoles(e)
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Globex.Key, map[string]any{"url": "https://hooks.globex.example/tally", "events": []string{"*"}}, &ep)
	e.MustDo(http.StatusNotFound, "DELETE", "/v1/webhook-endpoints/"+ep.ID, ms[store.RoleAdmin].key, nil, nil)
	e.MustDo(http.StatusOK, "GET", "/v1/webhook-endpoints/"+ep.ID, e.Globex.Key, nil, nil)
}

