// A role change applies to the member's existing keys at once.
func TestRoleChangeAppliesToExistingKeys(t *testing.T) {
	e := apitest.New(t)
	ms := addRoles(e)
	customer := map[string]string{"name": "New", "email": "new@example.com"}
	e.MustDo(http.StatusCreated, "POST", "/v1/customers", ms[store.RoleMember].key, customer, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+ms[store.RoleMember].id, e.Acme.Key, map[string]string{"role": "viewer"}, nil)
	if r := e.Do("POST", "/v1/customers", ms[store.RoleMember].key, map[string]string{"name": "Newer", "email": "newer@example.com"}); r.Code != http.StatusForbidden {
		t.Fatalf("demoted member writes: %s", r)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/customers", ms[store.RoleMember].key, nil, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+ms[store.RoleMember].id, e.Acme.Key, map[string]string{"role": "member"}, nil)
	e.MustDo(http.StatusCreated, "POST", "/v1/customers", ms[store.RoleMember].key, map[string]string{"name": "Newer", "email": "newer@example.com"}, nil)
}

func TestRemovingMembers(t *testing.T) {
	e := apitest.New(t)
	ms := addRoles(e)
	owner, admin, billing, member, viewer := ms[store.RoleOwner], ms[store.RoleAdmin], ms[store.RoleBilling], ms[store.RoleMember], ms[store.RoleViewer]

	// Removing someone else: owners and admins only, and not owners or admins unless one is an owner.
	e.MustDo(http.StatusForbidden, "DELETE", "/v1/members/"+billing.id, member.key, nil, nil)
	e.MustDo(http.StatusForbidden, "DELETE", "/v1/members/"+billing.id, viewer.key, nil, nil)
	e.MustDo(http.StatusForbidden, "DELETE", "/v1/members/"+owner.id, admin.key, nil, nil)
	e.MustDo(http.StatusNotFound, "DELETE", "/v1/members/usr_nope", owner.key, nil, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+billing.id, admin.key, nil, nil)

	// Anyone may leave, whatever their role.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+viewer.id, viewer.key, nil, nil)
	e.MustDo(http.StatusUnauthorized, "GET", "/v1/org", viewer.key, nil, nil)

	// Another owner lets the first one leave; the last owner cannot, and their refused leave changes nothing.
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+member.id, owner.key, map[string]string{"role": "owner"}, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+owner.id, owner.key, nil, nil)
	r := e.Do("DELETE", "/v1/members/"+member.id, member.key, nil)
	if r.Code != http.StatusConflict || r.Map(t)["error"] != "last_owner" {
		t.Fatalf("the last owner leaves: %s", r)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/org", member.key, nil, nil)
}

