func TestAPIKeysByRole(t *testing.T) {
	e := apitest.New(t)
	ms := addRoles(e)
	var all struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", e.Acme.Key, nil, &all)
	if len(all.Items) != 5 {
		t.Fatalf("the owner sees %d keys, want 5", len(all.Items))
	}
	keyID := map[string]string{}
	for _, k := range all.Items {
		keyID[k.Name] = k.ID
	}
	adminKey, memberKey := keyID["Key of admin@acme.example"], keyID["Key of member@acme.example"]
	var mine struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", ms[store.RoleViewer].key, nil, &mine)
	if len(mine.Items) != 1 || mine.Items[0].UserID != ms[store.RoleViewer].id {
		t.Fatalf("the viewer sees %+v, want only their own key", mine.Items)
	}
	var admin struct{ Items []store.APIKey }
	e.MustDo(http.StatusOK, "GET", "/v1/api-keys", ms[store.RoleAdmin].key, nil, &admin)
	if len(admin.Items) != 5 {
		t.Fatalf("the admin sees %d keys, want 5", len(admin.Items))
	}

	// Everyone may create a key for themselves.
	for role, m := range ms {
		e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", m.key, map[string]string{"name": "extra " + string(role)}, nil)
	}

	// Revoking: your own key always; anyone's for owners and admins; another member's key is 403 and still works.
	e.MustDo(http.StatusForbidden, "DELETE", "/v1/api-keys/"+adminKey, memberKey2(ms), nil, nil)
	e.MustDo(http.StatusOK, "GET", "/v1/org", ms[store.RoleAdmin].key, nil, nil)
	e.MustDo(http.StatusNotFound, "DELETE", "/v1/api-keys/key_nope", e.Acme.Key, nil, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+memberKey, ms[store.RoleAdmin].key, nil, nil)
	e.MustDo(http.StatusUnauthorized, "GET", "/v1/org", ms[store.RoleMember].key, nil, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+keyID["Key of viewer@acme.example"], ms[store.RoleViewer].key, nil, nil)
	e.MustDo(http.StatusUnauthorized, "GET", "/v1/org", ms[store.RoleViewer].key, nil, nil)
}

// memberKey2 is the key of the member whose own key the cases above do not revoke, so a refused revoke is tried from a
// key that stays valid.
func memberKey2(ms map[store.Role]member) string { return ms[store.RoleMember].key }

