func TestLastOwner(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	a, _ := s.CreateUser("a@acme.example", "A", t0)
	b, _ := s.CreateUser("b@acme.example", "B", t0)
	if _, err := s.AddMember(o.ID, a.ID, RoleOwner, t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.AddMember(o.ID, b.ID, RoleOwner, t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.SetMemberRole(o.ID, a.ID, RoleAdmin); err != nil {
		t.Fatalf("demoting one of two owners: %v", err)
	}
	// b is now the only owner.
	if _, err := s.SetMemberRole(o.ID, b.ID, RoleMember); !errors.Is(err, ErrLastOwner) {
		t.Fatalf("demoting the only owner: %v", err)
	}
	if err := s.RemoveMember(o.ID, b.ID); !errors.Is(err, ErrLastOwner) {
		t.Fatalf("removing the only owner: %v", err)
	}
	if m, _ := s.Member(o.ID, b.ID); m.Role != RoleOwner {
		t.Fatalf("the only owner's role changed to %s", m.Role)
	}
	if _, err := s.SetMemberRole(o.ID, b.ID, RoleOwner); err != nil {
		t.Fatalf("keeping the only owner an owner: %v", err)
	}
}

