156	func TestChangingRoles(t *testing.T) {
157		cases := []struct {
158			name        string
159			who, target store.Role
160			role        store.Role
161			want        int
162			wantErr     string
163		}{
164			{"admin grants admin", store.RoleAdmin, store.RoleMember, store.RoleAdmin, 403, "forbidden"},
165			{"admin grants billing", store.RoleAdmin, store.RoleMember, store.RoleBilling, 200, ""},
166			{"admin changes an owner", store.RoleAdmin, store.RoleOwner, store.RoleBilling, 403, "forbidden"},
167			{"admin changes an admin", store.RoleAdmin, store.RoleAdmin, store.RoleMember, 403, "forbidden"},
168			{"admin changes itself", store.RoleAdmin, store.RoleAdmin, store.RoleMember, 403, "forbidden"},
169			{"owner changes itself", store.RoleOwner, store.RoleOwner, store.RoleAdmin, 403, "forbidden"},
170			{"owner demotes an admin", store.RoleOwner, store.RoleAdmin, store.RoleBilling, 200, ""},
171			{"owner grants owner", store.RoleOwner, store.RoleMember, store.RoleOwner, 200, ""},
172			{"owner grants an unknown role", store.RoleOwner, store.RoleMember, "superuser", 422, "invalid"},
173			{"admin grants an unknown role", store.RoleAdmin, store.RoleMember, "superuser", 422, "invalid"},
174			{"billing changes a member", store.RoleBilling, store.RoleMember, store.RoleViewer, 403, "forbidden"},
175			{"member changes a viewer", store.RoleMember, store.RoleViewer, store.RoleMember, 403, "forbidden"},
176			{"viewer changes a member", store.RoleViewer, store.RoleMember, store.RoleViewer, 403, "forbidden"},
177		}
178		for _, c := range cases {
179			t.Run(c.name, func(t *testing.T) {
180				e := apitest.New(t)
181				ms := addRoles(e)
182				target := ms[c.target]
183				r := e.Do("PATCH", "/v1/members/"+target.id, ms[c.who].key, map[string]string{"role": string(c.role)})
184				if r.Code != c.want || (c.wantErr != "" && r.Map(t)["error"] != c.wantErr) {
185					t.Fatalf("want %d %s, got %s", c.want, c.wantErr, r)
186				}
187				m, _ := e.Store.Member(e.Acme.ID, target.id)
188				if c.want == 200 && m.Role != c.role {
189					t.Fatalf("role = %s, want %s", m.Role, c.role)
190				}
191				if c.want != 200 && m.Role != c.target {
192					t.Fatalf("a refused change moved the role to %s", m.Role)
193				}
194			})
195		}
196	}
