	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return ErrNotFound
	}
	if m.Role == RoleOwner && s.ownerCount(orgID) == 1 {
		return ErrLastOwner
	}
	delete(s.members, k)
	return nil
}

// ownerCount counts an organization's owners. The caller holds the lock.
func (s *Store) ownerCount(orgID string) int {
	n := 0
	for _, m := range s.members {
		if m.OrgID == orgID && m.Role == RoleOwner {
			n++
		}
	}
	return n
}

