// An owner with a co-owner may not change their own role, but the sole owner gets last_owner.
func TestOwnerChangesItselfWithCoOwner(t *testing.T) {
	e := apitest.New(t)
	ms := addRoles(e)
	co := e.AddMember(e.Acme, "co-owner@acme.example", store.RoleOwner)
	if r := e.Do("PATCH", "/v1/members/"+ms[store.RoleOwner].id, ms[store.RoleOwner].key, map[string]string{"role": "admin"}); r.Code != http.StatusForbidden || r.Map(t)["error"] != "forbidden" {
		t.Fatalf("owner with a co-owner changes itself: %s", r)
	}
	if m, _ := e.Store.Member(e.Acme.ID, ms[store.RoleOwner].id); m.Role != store.RoleOwner {
		t.Fatalf("refused self-demotion moved the role to %s", m.Role)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+co.ID, ms[store.RoleOwner].key, map[string]string{"role": "admin"}, nil)
	if r := e.Do("PATCH", "/v1/members/"+ms[store.RoleOwner].id, ms[store.RoleOwner].key, map[string]string{"role": "admin"}); r.Code != http.StatusConflict || r.Map(t)["error"] != "last_owner" {
		t.Fatalf("sole owner demotes itself: %s", r)
	}
